{
  "name": "USB忙闲指示灯",
  "name_en": "USB Busy Light",
  "manufacturer": "",
  "description": "一种通过USB连接的桌面状态指示灯，通常具有RGB发光和提示音功能，可用于实验室或工位场景中的状态显示、流程提醒和可视化告警。",
  "description_en": "A USB-connected desktop status indicator light, typically with RGB illumination and audible alert capability, used in labs or workstations for status indication, workflow prompts, and visual notifications.",
  "actions": [
    {
      "action_name": "auto-pulse",
      "description": "让指示灯以指定颜色脉冲发光。",
      "description_en": "Pulse the indicator light in a specified color."
    },
    {
      "action_name": "auto-available_colors",
      "description": "列出设备支持的预定义颜色。",
      "description_en": "List the predefined colors supported by the device."
    },
    {
      "action_name": "auto-set_sound",
      "description": "播放设备提示音并设置声音参数。",
      "description_en": "Play the device alert sound with specified sound settings."
    },
    {
      "action_name": "auto-set_rgb",
      "description": "设置RGB颜色值。",
      "description_en": "set RGB color value"
    },
    {
      "action_name": "auto-set_color",
      "description": "将指示灯设置为预定义颜色。",
      "description_en": "Set the indicator light to a predefined color."
    },
    {
      "action_name": "auto-blink",
      "description": "让指示灯以指定颜色闪烁。",
      "description_en": "Blink the indicator light in a specified color."
    },
    {
      "action_name": "auto-turn_off",
      "description": "关闭指示灯。",
      "description_en": "Turn off the indicator light."
    },
    {
      "action_name": "auto-send",
      "description": "将当前灯光或声音设置发送到设备并生效。",
      "description_en": "Send the current light or sound settings to the device and apply them."
    },
    {
      "action_name": "auto-get_rgb",
      "description": "获取RGB颜色值。",
      "description_en": "get RGB color value"
    }
  ],
  "tag_hints": [
    "USB status light",
    "busy light",
    "RGB indicator",
    "visual notification",
    "audible alert",
    "desktop occupancy indicator"
  ]
}

